import{_ as a,a0 as i,w as r,s as l,ao as d,I as o,x as t,a1 as p,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const u=JSON.parse('{"title":"如何在CentOS 7中禁止IPv6 | LCTT x X-CMD","titleTemplate":false,"description":"如何在CentOS 7中禁止IPv6 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在CentOS 7中禁止IPv6 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在CentOS 7中禁止IPv6 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150119 How To Disable IPv6 In CentOS 7","title":"如何在CentOS 7中禁止IPv6","tag":"201502","desc":""},"relativePath":"201502/20150119 How To Disable IPv6 In CentOS 7.md","filePath":"[post].md"}'),c={name:"201502/20150119 How To Disable IPv6 In CentOS 7.md"};function v(f,e,m,h,P,b){const n=i("Link");return r(),l("div",null,[e[13]||(e[13]=d(`<h1 id="如何在centos-7中禁止ipv6" tabindex="-1">如何在CentOS 7中禁止IPv6 <a class="header-anchor" href="#如何在centos-7中禁止ipv6" aria-label="Permalink to “如何在CentOS 7中禁止IPv6”">​</a></h1><p>最近，我的一位朋友問我該如何禁止IPv6。在搜索了一番之後，我找到了下面的方案。下面就是在我的CentOS 7 迷你服務器禁止IPv6的方法。</p><p>你可以用兩個方法做到這個。</p><h3 id="方法-1" tabindex="-1">方法 1 <a class="header-anchor" href="#方法-1" aria-label="Permalink to “方法 1”">​</a></h3><p>編輯文件<strong>/etc/sysctl.conf</strong>，</p><pre><code>vi /etc/sysctl.conf
</code></pre><p>添加下面的行：</p><pre><code>net.ipv6.conf.all.disable_ipv6 = 1
net.ipv6.conf.default.disable_ipv6 = 1
</code></pre><p>如果你想要為特定的網卡禁止IPv6，比如，對於enp0s3，添加下面的行。</p><pre><code>net.ipv6.conf.enp0s3.disable_ipv6 = 1
</code></pre><p>保存並退出文件。</p><p>執行下面的命令來使設置生效。</p><pre><code>sysctl -p
</code></pre><h3 id="方法-2" tabindex="-1">方法 2 <a class="header-anchor" href="#方法-2" aria-label="Permalink to “方法 2”">​</a></h3><p>要在運行的系統中禁止IPv6，依次輸入下面的命令：</p><pre><code>echo 1 &gt; /proc/sys/net/ipv6/conf/all/disable_ipv6
echo 1 &gt; /proc/sys/net/ipv6/conf/default/disable_ipv6
</code></pre><p>或者，</p><pre><code>sysctl -w net.ipv6.conf.all.disable_ipv6=1
sysctl -w net.ipv6.conf.default.disable_ipv6=1
</code></pre><p>就是這樣。現在IPv6已經禁止了。</p><h3 id="我在禁止ipv6後遇到問題怎麼辦" tabindex="-1">我在禁止IPv6後遇到問題怎麼辦 <a class="header-anchor" href="#我在禁止ipv6後遇到問題怎麼辦" aria-label="Permalink to “我在禁止IPv6後遇到問題怎麼辦”">​</a></h3><p>你可能在禁止IPv6後遇到一些問題</p><h4 id="問題1" tabindex="-1">問題1： <a class="header-anchor" href="#問題1" aria-label="Permalink to “問題1：”">​</a></h4><p>如果你在禁止IPv6後SSH遇到問題，按照下面的做。</p><p>編輯 <strong>/etc/ssh/sshd_config</strong> 文件</p><p>vi /etc/ssh/sshd_config</p><p>找到下面的行：</p><pre><code>#AddressFamily any
</code></pre><p>把它改成：</p><pre><code>AddressFamily inet
</code></pre><p>或者，在這行的前面去掉註釋<strong>(#)</strong>：</p><pre><code>#ListenAddress 0.0.0.0
</code></pre><p>接着重啓ssh來使改變生效。</p><pre><code>systemctl restart sshd
</code></pre><h4 id="問題2" tabindex="-1">問題2： <a class="header-anchor" href="#問題2" aria-label="Permalink to “問題2：”">​</a></h4><p>如果你在禁止Ipv6後啓動postfix遇到問題，編輯<strong>/etc/postfix/main.cf</strong>：</p><pre><code>vi /etc/postfix/main.cf
</code></pre><p>註釋掉配置中的localhost部分，並且使用ipv4迴環。</p><pre><code>#inet_interfaces = localhost
inet_interfaces = 127.0.0.1
</code></pre><p>就是這樣，乾杯！</p><hr>`,40)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),p(n,{href:"http://www.unixmen.com/disable-ipv6-centos-7/"},{default:s(()=>[...e[0]||(e[0]=[t("http://www.unixmen.com/disable-ipv6-centos-7/",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=t("作者：",-1)),p(n,{href:"http://www.unixmen.com/author/sk/"},{default:s(()=>[...e[2]||(e[2]=[t("SK",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),p(n,{href:"https://github.com/geekpi"},{default:s(()=>[...e[3]||(e[3]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:s(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),p(n,{href:"http://linux.cn/"},{default:s(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const T=a(c,[["render",v]]);export{u as __pageData,T as default};
